#!/usr/bin/env lua
-- Generates rust/src/unidata.rs from src/unidata.h.
--
--   lua scripts/rust-port/gen-unidata.lua [--check]
--
-- The Unicode tables in src/unidata.h (3753 lines) are the source of truth for
-- utf8extra's character classes, case conversion and width. Translating them by
-- hand invites silent drift, so rust/src/utf8.rs includes the generated file
-- instead. With --check, exits non-zero if the generated text differs from the
-- file on disk (the tables are otherwise only regenerated by hand).

local root = arg[0]:match("^(.*)/scripts/") or "."
local header = root .. "/src/unidata.h"
local output = root .. "/rust/src/unidata.rs"

local function read_file(path)
  local f = assert(io.open(path, "rb"), "cannot open " .. path)
  local s = f:read("a")
  f:close()
  return s
end

local src = read_file(header)

-- Every table is declared as
--   static struct range_table NAME_table[] = {  { first, last, step }, ...  };
--   static struct conv_table  NAME_table[] = {  { first, last, step, offset }, ...  };
local tables = {}
for kind, name, body in src:gmatch("static struct (%a+_table)%s+([%w_]+)_table%[%]%s*=%s*{(.-)};") do
  local entries = {}
  if kind == "range_table" then
    for first, last, step in body:gmatch("{%s*(0x%x+),%s*(0x%x+),%s*(-?%d+)%s*}") do
      entries[#entries + 1] = { tonumber(first), tonumber(last), tonumber(step) }
    end
  else
    for first, last, step, offset in
      body:gmatch("{%s*(0x%x+),%s*(0x%x+),%s*(-?%d+),%s*(-?%d+)%s*}") do
      entries[#entries + 1] = { tonumber(first), tonumber(last), tonumber(step), tonumber(offset) }
    end
  end
  assert(#entries > 0, "no entries parsed for " .. name .. "_table")
  tables[#tables + 1] = { name = name, kind = kind, entries = entries }
end

assert(#tables == 18, "expected 18 tables, found " .. #tables)

-- FNV-1a over the values, so drift shows up as a different number in review.
local function checksum(entries)
  local h = 2166136261
  for _, e in ipairs(entries) do
    for _, v in ipairs(e) do
      v = v % 4294967296
      for _ = 1, 4 do
        h = (h ~ (v & 0xFF)) & 0xFFFFFFFF
        h = (h * 16777619) & 0xFFFFFFFF
        v = v >> 8
      end
    end
  end
  return h
end

local out = {}
local function w(s) out[#out + 1] = s end

w("// @generated by scripts/rust-port/gen-unidata.lua from src/unidata.h -- do not edit.")
w("//")
w("// Lua's `string` library adapted to codepoints needs Unicode character classes,")
w("// case conversion and display width. The C core keeps these in src/unidata.h as")
w("// sorted range/offset tables; this file is the same data in Rust form.")
w("")
w("/// Sorted by `last`. A codepoint matches when it is inside `[first, last]` and")
w("/// `(cp - first) % step == 0`.")
w("pub type RangeTable = &'static [(u32, u32, i32)];")
w("")
w("/// Same lookup, but a match returns `cp + offset` instead of a boolean.")
w("pub type ConvTable = &'static [(u32, u32, i32, i32)];")
w("")

local summary = {}
for _, t in ipairs(tables) do
  local ty = t.kind == "range_table" and "RangeTable" or "ConvTable"
  w(("// %d entries, fnv1a 0x%08X"):format(#t.entries, checksum(t.entries)))
  w(("pub static %s_TABLE: %s = &["):format(t.name:upper(), ty))
  for _, e in ipairs(t.entries) do
    if #e == 3 then
      w(("    (0x%X, 0x%X, %d),"):format(e[1], e[2], e[3]))
    else
      w(("    (0x%X, 0x%X, %d, %d),"):format(e[1], e[2], e[3], e[4]))
    end
  end
  w("];")
  w("")
  summary[#summary + 1] = ("%-20s %6d entries  fnv1a 0x%08X"):format(
    t.name .. "_table", #t.entries, checksum(t.entries))
end

local text = table.concat(out, "\n")

if arg[1] == "--check" then
  local ok = pcall(read_file, output)
  if not ok then
    io.stderr:write("missing " .. output .. "\n")
    os.exit(1)
  end
  if read_file(output) ~= text then
    io.stderr:write(output .. " is out of date; re-run without --check\n")
    os.exit(1)
  end
  print(output .. " is up to date")
else
  local f = assert(io.open(output, "wb"))
  f:write(text)
  f:close()
  print("wrote " .. output)
  print(table.concat(summary, "\n"))
end
